  for(size_t i=0;i<15;++i) if(scan.mask & (1u<<i)) {
    feedback.positions[i]=scan.positions[i]; velocities[i]=scan.speeds[i];
    presentLoadRaw[i]=scan.loads[i]; positionReadUs[i]=scan.receivedUs[i];
    positionSeen |= uint16_t(1u<<i);
